//! Reading and writing `config.ini`.
//!
//! The format is whatever `INIFileParserDotNetCore` produced, because existing
//! installs have files written by it and those must keep working. Two details
//! of that format matter and are covered by
//! `tests/dotnet_config_compat.rs`:
//!
//! - values are written as `key = value`, with spaces around the `=`;
//! - the file carries a UTF-8 BOM.
//!
//! Both are handled here rather than left to the caller, and the regression
//! test reads a real file generated by the .NET code path rather than a
//! hand-written imitation.

use std::io;
use std::path::Path;

use ini::{Ini, WriteOption};

/// Section names, as the .NET app writes them.
const LOCK_SCREEN: &str = "LockScreen";
const VOICE: &str = "VoiceRecognition";

/// Appearance and behaviour, as stored. Credentials are deliberately not here --
/// see [`crate::credential`].
#[derive(Debug, Clone, PartialEq)]
pub struct Config {
    /// Prompt title.
    pub title: String,
    /// Overlay opacity, `0.0` (invisible) to `1.0` (opaque).
    pub transparency: f64,
    /// Whether to blur the desktop behind the overlay.
    pub blur_background: bool,
    /// Voice unlock settings.
    pub voice: VoiceConfig,
    /// The legacy DPAPI-encrypted password, if this file still has one.
    ///
    /// Present only in configs written by the .NET app. The port verifies
    /// against Argon2id hashes instead, so this exists to migrate the setting
    /// away, never to authenticate with.
    pub legacy_password: Option<String>,
    /// Argon2id PHC string for the normal unlock password.
    pub password_hash: Option<String>,
    /// Argon2id PHC string for the master password, set during first-run setup.
    pub master_hash: Option<String>,
}

/// Voice unlock settings. Off by default, and deliberately so: recognition is
/// speaker-independent, so anyone who can speak can trigger it.
#[derive(Debug, Clone, PartialEq)]
pub struct VoiceConfig {
    pub enabled: bool,
    pub unlock_command: String,
    pub confidence_threshold: f64,
    pub listening_timeout: u32,
}

impl Default for VoiceConfig {
    fn default() -> Self {
        Self {
            enabled: false,
            unlock_command: "unlock".to_owned(),
            // The .NET default of 0.7 is exactly the value WinRT's `Medium`
            // confidence maps to, so a medium-confidence match passes. The port
            // raises the floor; see RUST-MIGRATION.md §7.
            confidence_threshold: 1.0,
            listening_timeout: 10,
        }
    }
}

impl Default for Config {
    fn default() -> Self {
        Self {
            title: "Enter Password to Unlock".to_owned(),
            transparency: 0.5,
            blur_background: false,
            voice: VoiceConfig::default(),
            legacy_password: None,
            password_hash: None,
            master_hash: None,
        }
    }
}

impl Config {
    /// Whether first-run setup still has to happen.
    ///
    /// The overlay must refuse to start in this state: there is no credential
    /// to unlock with, and the .NET app's answer -- invent `1234` and show it
    /// in a dialog -- is exactly what the port removes.
    pub fn needs_setup(&self) -> bool {
        self.master_hash.is_none() || self.password_hash.is_none()
    }

    /// Clamp anything out of range rather than rejecting the file. A config
    /// someone hand-edited should still open the lock screen.
    fn sanitized(mut self) -> Self {
        self.transparency = self.transparency.clamp(0.0, 1.0);
        self.voice.confidence_threshold = self.voice.confidence_threshold.clamp(0.0, 1.0);
        if self.title.trim().is_empty() {
            self.title = Self::default().title;
        }
        if self.voice.unlock_command.trim().is_empty() {
            self.voice.unlock_command = VoiceConfig::default().unlock_command;
        }
        self
    }
}

/// Parse a config from INI text.
///
/// Tolerates a leading UTF-8 BOM, which the .NET writer emits.
pub fn parse(text: &str) -> Result<Config, ini::ParseError> {
    let text = text.strip_prefix('\u{feff}').unwrap_or(text);
    let ini = Ini::load_from_str(text)?;
    Ok(from_ini(&ini))
}

/// Read the config beside the executable, or [`Config::default`] if there is
/// none yet.
pub fn load(path: &Path) -> io::Result<Config> {
    match std::fs::read_to_string(path) {
        Ok(text) => parse(&text).map_err(|e| io::Error::new(io::ErrorKind::InvalidData, e)),
        Err(e) if e.kind() == io::ErrorKind::NotFound => Ok(Config::default()),
        Err(e) => Err(e),
    }
}

fn from_ini(ini: &Ini) -> Config {
    let d = Config::default();
    let get = |section: &str, key: &str| ini.get_from(Some(section), key).map(str::trim).filter(|v| !v.is_empty());

    let voice_default = VoiceConfig::default();
    Config {
        title: get(LOCK_SCREEN, "Title").map(str::to_owned).unwrap_or(d.title),
        transparency: get(LOCK_SCREEN, "Transparency").and_then(|v| v.parse().ok()).unwrap_or(d.transparency),
        blur_background: get(LOCK_SCREEN, "BlurBackground").and_then(parse_bool).unwrap_or(d.blur_background),
        voice: VoiceConfig {
            enabled: get(VOICE, "Enabled").and_then(parse_bool).unwrap_or(voice_default.enabled),
            unlock_command: get(VOICE, "UnlockCommand")
                .map(|v| v.to_lowercase())
                .unwrap_or(voice_default.unlock_command),
            confidence_threshold: get(VOICE, "ConfidenceThreshold")
                .and_then(|v| v.parse().ok())
                .unwrap_or(voice_default.confidence_threshold),
            listening_timeout: get(VOICE, "ListeningTimeout")
                .and_then(|v| v.parse().ok())
                .unwrap_or(voice_default.listening_timeout),
        },
        legacy_password: get(LOCK_SCREEN, "Password").map(str::to_owned),
        password_hash: get(LOCK_SCREEN, "PasswordHash").map(str::to_owned),
        master_hash: get(LOCK_SCREEN, "MasterHash").map(str::to_owned),
    }
    .sanitized()
}

/// Write a config, replacing whatever was there.
///
/// Writes `key = value` to match what the .NET app produced, so a file that
/// round-trips through both tools does not churn. No BOM: it is not needed, and
/// this parser tolerates its absence either way.
pub fn save(path: &Path, config: &Config) -> io::Result<()> {
    let mut ini = Ini::new();
    {
        let mut section = ini.with_section(Some(LOCK_SCREEN));
        section
            .set("Title", &config.title)
            .set("Transparency", format!("{:.3}", config.transparency))
            .set("BlurBackground", bool_str(config.blur_background));
        if let Some(hash) = &config.password_hash {
            section.set("PasswordHash", hash);
        }
        if let Some(hash) = &config.master_hash {
            section.set("MasterHash", hash);
        }
    }
    ini.with_section(Some(VOICE))
        .set("Enabled", bool_str(config.voice.enabled))
        .set("UnlockCommand", &config.voice.unlock_command)
        .set("ConfidenceThreshold", format!("{:.2}", config.voice.confidence_threshold))
        .set("ListeningTimeout", config.voice.listening_timeout.to_string());

    // Note what is absent: the legacy `Password` key is never written back.
    // Reading a .NET config migrates the settings and drops the reversible
    // credential rather than carrying it forward.
    // `key = value`, with the spaces, because that is what
    // INIFileParserDotNetCore wrote. rust-ini defaults to `key=value`, so a
    // file touched by both tools would otherwise churn on every save. The
    // compatibility test asserts this rather than trusting the default.
    let mut out = Vec::new();
    ini.write_to_opt(&mut out, WriteOption { kv_separator: " = ", ..WriteOption::default() })?;
    std::fs::write(path, out)
}

fn bool_str(value: bool) -> &'static str {
    if value { "true" } else { "false" }
}

/// `bool.TryParse` in .NET accepts only `true`/`false`, case-insensitively, but
/// hand-edited files turn up with `1`, `yes` and `on`, so accept those too.
fn parse_bool(value: &str) -> Option<bool> {
    match value.trim().to_ascii_lowercase().as_str() {
        "true" | "1" | "yes" | "on" => Some(true),
        "false" | "0" | "no" | "off" => Some(false),
        _ => None,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_missing_file_yields_defaults_rather_than_an_error() {
        let config = load(Path::new("Z:/no/such/config.ini")).expect("defaults");
        assert_eq!(config, Config::default());
        assert!(config.needs_setup());
    }

    #[test]
    fn out_of_range_values_are_clamped_not_rejected() {
        let config = parse("[LockScreen]\nTransparency = 9.5\n").expect("parsed");
        assert_eq!(config.transparency, 1.0);
        let config = parse("[LockScreen]\nTransparency = -3\n").expect("parsed");
        assert_eq!(config.transparency, 0.0);
    }

    #[test]
    fn an_empty_title_falls_back_to_the_default() {
        let config = parse("[LockScreen]\nTitle = \n").expect("parsed");
        assert_eq!(config.title, Config::default().title);
    }

    #[test]
    fn booleans_accept_the_spellings_hand_edited_files_use() {
        for (text, expected) in [("true", true), ("TRUE", true), ("1", true), ("on", true), ("no", false)] {
            let config = parse(&format!("[LockScreen]\nBlurBackground = {text}\n")).expect("parsed");
            assert_eq!(config.blur_background, expected, "for {text:?}");
        }
    }

    #[test]
    fn setup_is_needed_until_both_hashes_exist() {
        let mut config = Config::default();
        assert!(config.needs_setup());
        config.password_hash = Some("x".into());
        assert!(config.needs_setup(), "a password alone is not enough");
        config.master_hash = Some("y".into());
        assert!(!config.needs_setup());
    }

    #[test]
    fn saving_never_writes_the_legacy_password_back() {
        let dir = std::env::temp_dir().join(format!("lockscreen-cfg-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("a temp dir");
        let path = dir.join("config.ini");

        let config = Config { legacy_password: Some("AQAAANCM-pretend-blob".into()), ..Config::default() };
        save(&path, &config).expect("saved");

        let text = std::fs::read_to_string(&path).expect("read back");
        assert!(!text.contains("AQAAANCM-pretend-blob"));
        assert!(!text.contains("Password ="), "no reversible credential should survive a save");
        assert!(text.contains("Title ="));

        let _ = std::fs::remove_dir_all(&dir);
    }

    #[test]
    fn a_saved_config_round_trips() {
        let dir = std::env::temp_dir().join(format!("lockscreen-rt-{}", std::process::id()));
        std::fs::create_dir_all(&dir).expect("a temp dir");
        let path = dir.join("config.ini");

        let config = Config {
            title: "Unlock this machine".into(),
            transparency: 0.25,
            blur_background: true,
            password_hash: Some("$argon2id$v=19$m=19456,t=2,p=1$c2FsdHlzYWx0$aGFzaA".into()),
            master_hash: Some("$argon2id$v=19$m=19456,t=2,p=1$b3RoZXJzYWx0$bWFzdGVy".into()),
            ..Config::default()
        };
        save(&path, &config).expect("saved");
        assert_eq!(load(&path).expect("loaded"), config);

        let _ = std::fs::remove_dir_all(&dir);
    }
}
